comms.text:
@1 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@2 פַּקֵד יָת אַהֲרֹן וְיָת בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דַעֲלָתָא הִיא עֲלָתָא דְמִתּוֹקְדָא עַל מַדְבְּחָא כָל לֵילְיָא עַד צַפְרָא וְאֶשָׁתָא דְמַדְבְּחָא תְּהֵא יָקְדָא בֵהּ:
@3 וְיַלְבֵּשׁ כַּהֲנָא לְבוּשִׁין דְבוּץ וּמִכְנְסִין דְבוּץ יַלְבֵּשׁ עַל בִּסְרֵהּ וְיַפְרֵשׁ יָת קִטְמָא דִי תֵיכוּל אֶשָׁתָא יָת עֲלָתָא עַל מַדְבְּחָא וִישַׁוִנֵהּ בִּסְטַּר מַדְבְּחָא:
@4 וְיַשְׁלַח יָת לְבוּשׁוֹהִי וְיִלְבַּשׁ לְבוּשִׁין אָחֳרָנִין וְיַפֵּק יָת קִטְמָא לְמִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְכֵי:
@5 וְאֶשָׁתָא עַל מַדְבְּחָא תְהֵי יָקְדָא בֵהּ לָא תִטְּפֵי וְיַבְעַר עֲלַהּ כַּהֲנָא אָעַיָא בִּצְפַר בִּצְפָר וְיַסְדַר עֲלַהּ עֲלָתָא וְיַסֵק עֲלַהּ תַּרְבֵּי נִכְסַת קוּדְשַׁיָא:
@6 אֶשָׁתָא תְּדִירָא תְּהֵי יָקְדָא עַל מַדְבְּחָא לָא תִטְפֵי:
@7 וְדָא אוֹרַיְתָא דְמִנְחָתָא דִיקָרְבוּן יָתַהּ בְּנֵי אַהֲרֹן קֳדָם יְיָ לָקֳדָם מַדְבְּחָא:
@8 וְיַפְרֵשׁ מִנֵהּ בְּקֻמְצֵהּ מִסֻלְתָּא דְמִנְחָתָא וּמִמִשְׁחַהּ וְיָת כָּל לְבוּנְתָּא דִי עַל מִנְחָתָא וְיַסֵק לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא אַדְכַּרְתָּא קֳדָם יְיָ:
@9 וּדְאִשְׁתָּאַר מִנַהּ יֵכְלוּן אַהֲרֹן וּבְנוֹהִי פַּטִיר תִּתְאַכֵל בַּאֲתַר קַדִּישׁ בְּדָרַת מַשְׁכַּן זִמְנָא יֵכְלֻנַהּ:
@10 לָא תִתְאֲפֵי חֲמִיעַ חָלָקְהוֹן יְהָבִית יָתַהּ מִקֻרְבָּנָי קֹדֶשׁ קוּדְשִׁין הִיא כְּחַטָאתָא וְכַאֲשָׁמָא:
@11 כָּל דְכוּרָא בִּבְנֵי אַהֲרֹן יֵכְלֻנַהּ קְיָם עָלָם לְדָרָתֵיכוֹן מִקֻרָבָּנַיָא דַיְיָ כֹּל דְיִקְרַב בְּהוֹן יִתְקַדָּשׁ:
@12 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@13 דֵין קֻרְבַּן אַהֲרֹן וּבְנוֹהִי דִי יְקָרְבוּן קֳדָם יְיָ בְּיוֹמָא דְרַבִּיאוּ יָתֵהּ חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא מִנְחָתָא תְּדִירָא פַּלְגוּתַהּ בְּצַפְרָא וּפַלְגוּתַהּ בְּרַמְשָׁא:
@14 עַל מַסְרֵיתָא בִּמְשַׁח תִּתְעֲבֵד רְבִיכָא תַיְתִנַהּ תּוּפִינֵי מִנְחַת בִּצוּעִין תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@15 וְכַהֲנָא דִמְרַבָּא תְחוֹתוֹהִי מִבְּנוֹהִי יַעְבֵּד יָתַהּ קְיָם עָלָם קֳדָם יְיָ גְמִיר תִּתַּסָק:
@16 וְכָל מִנְחָתָא דְכַהֲנָא גְמִיר תְּהֵי לָא תִתְאֲכֵל:
@17 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@18 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דְחַטָאתָא בַּאֲתַר דִי תִתְנְכֵס עֲלָתָא תִּתְנְכֵס חַטָאתָא קֳדָם יְיָ קֹדֶשׁ קוּדְשִׁין הִיא:
@19 כַּהֲנָא דִמְכַפֵּר בִּדְמַהּ יֵיכְלִנַהּ בַּאֲתַר קַדִישׁ תִּתְאֲכֵל בְּדָרַת מַשְׁכַּן זִמְנָא:
@20 כֹּל דִי יִקְרַב בְּבִסְרַהּ יִתְקַדַשׁ וְדִי יַדִי מִדְמַהּ עַל לְבוּשׁ דִי יַדִי עֲלַהּ תִּתְחַוָר בַּאֲתַר קַדִישׁ:
@21 וּמָן דַחֲסַף דִי תִתְבַּשֵׁל בֵּהּ יִתָּבָר וְאִם בְּמָנָא דִנְחָשָׁא תִּתְבַּשֵׁל וְיִתְמְרֵק וְיִשְׁתַּטֵף בְּמַיָא:
@22 כָּל דְכוּרָא בְּכַהֲנַיָא יֵכוּל יָתַהּ קֹדֶשׁ קוּדְשִׁין הִיא:
@23 וְכָל חַטָאתָא דִי יִתָּעַלּ מִדְמַהּ לְמַשְׁכַּן זִמְנָא לְכַפָּרָא בְקוּדְשָׁא לָא תִתְאֲכֵל בְּנוּרָא תִּתּוֹקָד:
@24 וְדָא אוֹרַיְתָא דַאֲשָׁמָא קֹדֶשׁ קוּדְשִׁין הוּא:
@25 בְּאַתְרָא דִי יִכְּסוּן יָת עֲלָתָא יִכְּסוּן יָת אֲשָׁמָא וְיָת דְמֵהּ יִזְרַק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@26 וְיָת כָּל תַּרְבֵּהּ יַפְרֵשׁ מִנֵהּ יָת אֲלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא:
@27 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חִצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@28 וְיַסֵיק יָתְהוֹן כַּהֲנָא לְמַדְבְּחָא קוּרְבָּנָא קֳדָם יְיָ אֲשָׁמָא הוּא:
@29 כָּל דְכוּרָא בְּכַהֲנַיָא יֵיכְלִנֵהּ בַּאֲתַר קַדִישׁ יִתְאֲכָל קוֹדֶשׁ קוּדְשִׁין הוּא:
@30 כְּחַטָאתָא כַּאֲשָׁמָא אוֹרַיְתָא חֲדָא לְהוֹן כַּהֲנָא דִי יְכַפֵּר בֵּהּ דִילֵהּ יְהֵי:
@31 וְכַהֲנָא דִמְקָרֵב יַת עֲלַת גְבַר מְשַׁךְ עֲלָתָא דִי יְקָרֵב לְכַהֲנָא דִילֵהּ יְהֵי:
@32 וְכָל מִנְחָתָא דִי תִתְאֲפֵי בְּתַנוּרָא וְכָל דְתִתְעֲבֵד בְּרִדְתָּא וְעַל מַסְרֵיתָא לְכַהֲנָא דִמְקָרֵב יָתַהּ דִילֵהּ תְּהֵי:
@33 וְכָל מִנְחָתָא דְפִילָא בִמְשַׁח וּדְלָא פִילָא לְכָל בְּנֵי אַהֲרֹן תְּהֵי גְבַר כַּאָחוֹהִי:
@34 וְדָא אוֹרַיְתָא דְנִכְסַת קוּדְשַׁיָא דִי יְקָרֵב קֳדָם יְיָ:
@35 אִם עַל תּוֹדְתָא יְקָרְבִנֵהּ וִיקָרֵב עַל נִכְסַת תּוֹדְתָא גְרִיצָן פַּטִירָן דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִירִין דִּמְשִׁיחִין בִּמְשָׁח וְסוּלְתָּא רְבִיכָא גְרִיצָן דְפִילָן בִּמְשָׁח:
@36 עַל גְּרִיצָן דִלְחֵם חָמִיעַ יְקָרֵב קוּרְבָּנֵיהּ עַל נִכְסַת תּוֹדַת קוּדְשׁוֹהִי:
@37 וִיקָרֵב מִנֵהּ חַד מִכָּל קוּרְבַּן אַפְרָשׁוּתָא קֳדָם יְיָ לְכַהֲנָא דְיִזְרַק יָת דַם נִכְסַת קוּדְשַׁיָא דִילֵהּ יְהֵי:
@38 וּבְשַׂר נִכְסַת תּוֹדַת קוּדְשׁוֹהִי בְּיוֹם קֻרְבָּנֵהּ יִתְאֲכֵל לָא יַצְנַע מִנֵהּ עַד צַפְרָא:
@39 וְאִם נִדְרָא אוֹ נְדַבְתָּא נִכְסַת קֻרְבָּנֵהּ בְּיוֹמָא דִי יְקָרֵב יָת נִכְסְתֵיהּ יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר מִנֵהּ יִתְאֲכֵלּ:
@40 וּדְאִשְׁתָּאַר מִבְּסַר נִכְסָתָא בְּיוֹמָא תְּלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@41 וְאִם אִתְאֲכָלָא יִתְאֲכֵל מִבְּסַר נִכְסַת קוּדְשׁוֹהִי בְּיוֹמָא תְּלִיתָאָה לָא יְהֵי לְרַעֲוָא דִמְקָרֵב יָתֵהּ לָא יִתְחַשֵׁב לֵהּ מְרָחָק יְהֵי וֶאֱנַשׁ דְתֵכוּל מִנֵהּ חוֹבֵהּ יְקַבֵּל:
@42 וּבְסַר קוּדְשָׁא דִי יִקְרַב בְּכָל מְסָאָב לָא יִתְאֲכֵל בְּנוּרָא יִתּוֹקָד וּבְסַר קוּדְשָׁא כָּל דִי דְכֵי לְקוּדְשָׁא יֵיכוּל בְּסַר קוּדְשָׁא:
@43 וֶאֱנַשׁ דִי תֵכוּל בִּסְרָא מִנִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְסוֹבְתֵהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@44 וֶאֱנַשׁ אֲרֵי תִקְרַב בְּכָל מְסָאָב בְסוֹאֲבַת אֱנָשָׁא אוֹ בִּבְעִירָא מְסָאֲבָא אוֹ בְּכָל שִׁקְצָא מְסָאָב וְיֵיכוּל מִבְּסַר נִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@45 וּמַלֵיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@46 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר כָּל תְּרַב תּוֹר וְאִמַר וְעִזָא לָא תֵיכְלוּן:
@47 וּתְרַב נְבִילָא וּתְרַב תְּבִירָא יִתְעֲבֵד לְכָל עִבִדְתָּא וּמֵיכַל לָא תֵיכְלוּנֵהּ:
@48 אֲרֵי כָל דְיֵכוּל תַּרְבָּא מִן בְּעִירָא דִי יִקָרְבוּן מִנַהּ קוּרְבָּנָא קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא דִי תֵיכוּל מֵעַמַּהּ:
@49 וְכָל דְמָא לָא תֵיכְלוּן בְּכֹל מוֹתְבָנֵיכוֹן דְעוֹפָא וְדִבְעִירָא:
@50 כָּל אֱנָשָׁא דִי תֵיכוּל כָּל דְמָא וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַהּ:
@51 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@52 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דִמְקָרֵב יָת נִכְסַת קוּדְשׁוֹהִי קֳדָם יְיָ יַיְתִי יָת קֻרְבָּנֵהּ לָקֳדָם יְיָ מִנִכְסַת קוּדְשׁוֹהִי:
@53 יְדוֹהִי תַיְתוּן יָת קֻרְבָּנַיָא דַיְיָ יָת תַּרְבָּא עַל חַדְיָא יַיְתִנֵהּ יָת חֶדְיָא לַאֲרָמָא יָתֵהּ אֲרוּמָא קֳדָם יְיָ:
@54 וְיַסֵק כַּהֲנָא יָת תַּרְבָּא לְמַדְבְּחָא וִיהֵי חֶדְיָא לְאַהֲרֹן וְלִבְנוֹהִי:
@55 וְיָת שׁוֹקָא דְיַמִינָא תִּתְּנוּן אַפְרָשׁוּתָא לְכַהֲנָא מִנִכְסַת קוּדְשֵׁיכוֹן:
@56 דִמְקָרֵב יָת דָם נִכְסַת קוּדְשַׁיָא וְיָת תַּרְבָּא מִבְּנֵי אַהֲרֹן דִילֵהּ תְּהֵי שׁוֹקָא דְיַמִינָא לָחֳלָק:
@57 אֲרֵי יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא נְסֵבִית מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן וִיהָבִית יָתְהוֹן לְאַהֲרֹן כַּהֲנָא וְלִבְנוֹהִי לִקְיָם עָלָם מִן בְּנֵי יִשְׂרָאֵל:
@58 דָא רְבוּת אַהֲרֹן וּרְבוּת בְּנוֹהִי מִקוּרְבָּנַיָא דַיְיָ בְּיוֹמָא דְקָרֵב יָתְהוֹן לְשַׁמָשָׁא קֳדָם יְיָ:
@59 דִי פַקִיד יְיָ לְמִתַּן לְהוֹן בְּיוֹמָא דְרַבִּי יָתְהוֹן מִן בְּנֵי יִשְׂרָאֵל קְיָם עָלָם לְדָרֵיהוֹן:
@60 דָא אוֹרַיְתָא לַעֲלָתָא לְמִנְחָתָא וּלְחַטָּאתָא וְלַאֲשָׁמָא וּלְקוּרְבָּנַיָא וּלְנִכְסַת קוּדְשַׁיָא:
@61 דִי פַקִיד יְיָ יָת מֹשֶׁה בְּטוּרָא דְסִינָי בְּיוֹמָא דְפַקְדֵהּ יָת בְּנֵי יִשְׂרָאֵל לְקָרָבָא יָת קֻרְבָּנְהוֹן קֳדָם יְיָ בְּמַדְבְּרָא דְסִינָי:
@62 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@63 קָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי עִמֵהּ וְיָת לְבוּשַׁיָא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת תּוֹרָא דְחַטָאתָא וְיָת תְּרֵין דִכְרִין וְיָת סַלָא דְפַטִירַיָא:
@64 וְיָת כָּל כְּנִשְׁתָּא כְּנֵשׁ לִתְרַע מַשְׁכַּן זִמְנָא:
@65 וַעֲבַד מֹשֶׁה כְּמָא דִי פַקִיד יְיָ יָתֵהּ וְאִתְכְּנִשַׁת כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:
@66 וַאֲמַר מֹשֶׁה לִכְנִשְׁתָּא דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֶעְבָּד:
@67 וְקָרִיב מֹשֶׁה יָת אַהֲרֹן וְיָת בְּנוֹהִי וְאַסְחֵי יָתְהוֹן בְּמַיָא:
@68 וִיהַב עֲלוֹהִי יָת כִּתּוּנָא וְזָרֵז יָתֵהּ בְּהֶמְיָנָא וְאַלְבֵּשׁ יָתֵהּ יָת מְעִילָא וִיהַב עֲלוֹהִי יָת אֵפוֹדָא וְזָרֵז יָתֵהּ בְּהֶמְיַן אֵפוֹדָא וְאַתְקֵן לֵהּ בֵּהּ:
@69 וְשַׁוִי עֲלוֹהִי יָת חוּשְׁנָא וִיהַב בְּחוּשְׁנָא יָת אוּרַיָא וְיָת תֻּמַיָא:
@70 וְשַׁוִי יָת מִצְנַפְתָּא עַל רֵישֵׁיהּ וְשַׁוִי עַל מִצְנֶפְתָּא לָקֳבֵיל אַפּוֹהִי יָת צִיצָא דְדַהֲבָא כְּלִילָא דְקוּדְשָׁא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@71 וּנְסִיב מֹשֶׁה יָתּ מִשְׁחָא דִרְבוּתָא וְרַבִּי יָת מַשְׁכְּנָא וְיָת כָּל דִי בֵהּ וְקַדִישׁ יָתְהוֹן:
@72 וְאַדִי מִנֵהּ עַל מַדְבְּחָא שְׁבַע זִמְנִין וְרַבִּי יָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְיָת כִּיוֹרָא וְיָת בְּסִיסֵהּ לְקַדָשׁוּתְהוֹן:
@73 וַאֲרֵיק מִמִשְׁחָא דִרְבוּתָא עַל רֵישָׁא דְאַהֲרֹן וְרַבִּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@74 וְקָרִיב מֹשֶׁה יָת בְּנֵי אַהֲרֹן וְאַלְבֵּשִׁנוּן כִּתּוּנִין וְזָרֵז יָתְהוֹן הֶמְיָנִין וְאַתְקֵן לְהוֹן כּוֹבָעִין כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@75 וְקָרֵב יָת תּוֹרָא דְחַטָאתָא וּסְמַךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא דְחַטָאתָא:
@76 וּנְכֵס וּנְסִיב מֹשֶׁה יָת דְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר בְּאֶצְבְּעֵהּ וְדַכִּי יָת מַדְבְּחָא וְיָת דְמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא וְקַדְשֵׁהּ לְכַפָּרָא עֲלוֹהִי:
@77 וּנְסִיב יָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְאַסֵק מֹשֶׁה לְמַדְבְּחָא:
@78 וְיָת תּוֹרָא וְיָת מַשְׁכֵהּ וְיָת בִּסְרֵהּ וְיָת אָכְלֵהּ אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@79 וְקָרִיב יָת דִכְרָא דַעֲלָתָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@80 וּנְכֵס וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@81 וְיָת דִכְרָא פַּלֵג לְאֶבְרוֹהִי וְאַסֵק מֹשֶׁה יָת רֵישָׁא וְיָת אֶבְרַיָא וְיָת תַּרְבָּא:
@82 וְיָת גַוָא וְיָת כְּרָעַיָא חַלִיל בְּמַיָא וְאַסֵק מֹשֶׁה יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא לְאִתְקַבָּלָא בְרַעִוָא קוּרְבָּנָא הוּא קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@83 וְקָרִיב יָת דִכְרָא תִנְיָנָא דְכַר קוּרְבָּנַיָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@84 וּנְכֵס וּנְסִיב מֹשֶׁה מִן דְמָא וִיהַב עַל רוּם אוּדְנָא דְאַהֲרֹן דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@85 וְקָרֵיב יָת בְּנֵי אַהֲרֹן וִיהַב מֹשֶׁה מִן דְמָא עַל רוּם אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@86 וּנְסִיב יָת תַּרְבָּא וְיָת אֲלִיתָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְיָת שׁוֹקָא דְיַמִינָא:
@87 וּמִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ נְסִיב גְרִצְתָּא פַטִירָא חֲדָא וּגְרִיצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד וְשַׁוִי עַל תַּרְבַּיָא וְעַל שׁוֹקָא דְיַמִינָא:
@88 וִיהַב יָת כֹּלָא עַל יְדֵי אַהֲרֹן וְעַל יְדֵי בְנוֹהִי וַאֲרֵים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@89 וּנְסִיב מֹשֶׁה יָתְהוֹן מֵעַל יְדֵיהוֹן וְאַסֵק לְמַדְבְּחָא עַל עֲלָתָא קוּרְבָּנַיָא אִנוּן לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא הוּא קֳדָם יְיָ:
@90 וּנְסִיב מֹשֶׁה יָת חֶדְיָא וַאֲרִימֵהּ אֲרָמָא קֳדָם יְיָ מִדְכַר קוּרְבָּנַיָא לְמֹשֶׁה הֲוָה לָחֳלָק כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@91 וּנְסִיב מֹשֶׁה מִמִשְׁחָא דִרְבוּתָא וּמִן דְמָא דִי עַל מַדְבְּחָא וְאַדִי עַל אַהֲרֹן עַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְקַדִישׁ יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְיָת בְּנוֹהִי וְיָת לְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@92 וַאֲמַר מֹשֶׁה לְאַהֲרֹן וְלִבְנוֹהִי בַּשִׁילוּ יָת בִּסְרָא בִּתְרַע מַשְׁכַּן זִמְנָא וְתַמָן תֵּיכְלוּן יָתֵהּ וְיָת לַחְמָא דִי בְּסַל קוּרְבָּנַיָא כְּמָא דִי פַקֵדִית לְמֵימָר אַהֲרֹן וּבְנוֹהִי יֵיכְלוּנֵהּ:
@93 וּדְאִשְׁתָּאַר בְּבִשְׂרָא וּבְלַחְמָא בְּנוּרָא תּוֹקְדוּן:
@94 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן שִׁבְעָא יוֹמִין עַד יוֹם מִשְׁלַם יוֹמֵי קוּרְבָּנֵיכוֹן אֲרֵי שִׁבְעָא יוֹמִין יְקָרֵב יָת קֻרְבָּנֵיכוֹן:
@95 כְּמָא דִי עֲבַד בְּיוֹמָא הָדֵין פָּקִיד יְיָ לְמֶעְבַּד לְכַפָּרָא עֲלֵיכוֹן:
@96 וּבִתְרַע מַשְׁכַּן זִמְנָא תֵּיתְבוּן יְמָם וְלֵילֵי שִׁבְעָא יוֹמִין וְתִטְרוּן יָת מַטְרַת מֵימְרָא דַיְיָ וְלָא תְמוּתוּן אֲרֵי כֵן אִתְפַּקָדִית:
@97 וַעֲבַד אַהֲרֹן וּבְנוֹהִי יָת כָּל פִּתְגָמַיָא דִי פַקִיד יְיָ בִּידָא דְמֹשֶׁה: פפפ:

@2 **צו את אהרן.** אין צו אלא לשון זרוז מיד ולדורות. אמר ר' שמעון ביותר צריך הכתוב לזרז במקום שיש בו חסרון כיס: **זאת תורת העלה** וגו' **.** הרי הענין הזה בא ללמד על הקטר חלבים ואיברים שיהא כשר כל הלילה, וללמד על הפסולין איזה אם עלה ירד, ואיזה אם עלה לא ירד, שכל תורה לרבות הוא בא, לומר תורה אחת לכל העולים, ואפלו פסולין, שאם עלו לא ירדו: **הוא העלה.** למעט את הרובע ואת הנרבע וכיוצא בהן, שלא היה פסולן בקדש, שנפסלו קודם שבאו לעזרה:
@3 **מדו בד.** היא הכתנת. ומה תלמוד לומר מדו, שתהא כמדתו: **על בשרו.** שלא יהא דבר חוצץ בנתים: **והרים את הדשן.** היה חותה מלא מחתה מן המאכלות הפנימיות ונותנן במזרחו של כבש: **הדשן אשר תאכל האש את העלה.** ועשאתה דשן, מאותו דשן ירים תרומה ושמו אצל המזבח: **על המזבח.** מצא אברים שעדין לא נתעכלו, מחזירן על המזבח, לאחר שחתה גחלים אלך ואלך ונטל מן הפנימיות, שנאמר את העלה על המזבח:
@4 **ופשט את בגדיו.** אין זו חובה אלא דרך ארץ, שלא ילכלך בהוצאת הדשן בגדים שהוא משמש בהן תמיד. בגדים שבשל בהן קדרה לרבו אל ימזג בהן כוס לרבו, לכך ולבש בגדים אחרים פחותין מהן: **והוציא את הדשן.** הצבור בתפוח, כשהוא רבה ואין מקום למערכה, מוציאו משם. ואין זה חובה בכל יום, אבל התרומה חובה בכל יום ה **והאש על המזבח תוקד בו.** רבה כאן יקידות הרבה על מוקדה, ואש המזבח תוקד בו, והאש על המזבח תוקד בו, אש תמיד תוקד על המזבח, כלן נדרשו במסכת יומא (מג ב) שנחלקו רבותינו במנין המערכות שהיו שם: **וערך עליה העלה.** עולת תמיד היא תקדים: **חלבי השלמים.** אם יביאו שם שלמים. ורבותינו למדו מכאן עליה, על עולת הבקר השלם כל הקרבנות כלם. מכאן שלא יהא דבר מאוחר לתמיד של בין הערבים:
@6 **אש תמיד.** אש שנאמר בה תמיד, היא שמדליקין בה את הנרות, שנאמר בה (שמות כז כ) להעלות נר תמיד, אף היא מעל המזבח החיצון תוקד: **לא תכבה.** המכבה אש על המזבח עובר בשני לאוין:
@7 **וזאת תורת המנחה.** תורה אחת לכלן להטעינן שמן ולבונה האמורין בענין. שיכול אין לי טעונות שמן ולבונה אלא מנחת ישראל שהיא נקמצת, מנחת כהנים שהיא כליל מנין, תלמוד לומר תורת: **הקרב אתה.** היא הגשה בקרן מערבית דרומית: **לפני ה'.** הוא מערב שהוא לצד אהל מועד: **אל פני המזבח.** הוא הדרום, שהוא פניו של מזבח, שהכבש נתון לאותו הרוח:
@8 **והרים ממנו.** מהמחבר, שיהא עשרון שלם בבת אחת בשעת קמיצה: **בקמצו.** שלא יעשה מדה לקומץ: **מסלת המנחה ומשמנה.** מכאן שקומץ ממקום שנתרבה שמנה: **המנחה.** שלא תהא מעורבת באחרת: **ואת כל הלבנה אשר על המנחה והקטיר.** שמלקט את לבונתה לאחר קמיצה ומקטירו. ולפי שלא פרש כן אלא באחת מן המנחות בויקרא (ב, א. ג) , הצרך לשנות פרשה זו, לכלול כל המנחות כמשפטן:
@9 **במקום קדש.** ואיזהו, בחצר אהל מועד:
@10 **לא תאפה חמץ חלקם.** אף השירים אסורים בחמץ: **כחטאת וכאשם.** מנחת חוטא הרי היא כחטאת, לפיכך קמצה שלא לשמה פסולה. מנחת נדבה הרי היא כאשם, לפיכך קמצה שלא לשמה כשרה:
@11 **כל זכר.** אפלו בעל מום. למה נאמר, אם לאכילה הרי כבר אמור לחם אלהיו מקדשי הקדשים וגו' , אלא לרבות בעלי מומין למחלוקת: **כל אשר יגע** וגו' **.** קדשים קלים או חלין שיגעו בה ויבלעו ממנה: **יקדש.** להיות כמוה, שאם פסולה יפסלו, ואם כשרה יאכלו כחמר המנחה:
@13 **זה קרבן אהרן ובניו.** אף ההדיוטות מקריבין עשירית האיפה ביום שהן מתחנכין לעבודה, אבל כהן גדול בכל יום, שנאמר מנחה תמיד וגו' והכהן המשיח תחתיו מבניו וגו' חק עולם וגו' (פסוק טו) יד **מרבכת.** חלוטה ברותחין כל צרכה: **תפיני.** אפויה אפיות הרבה, שאחר חליטתה אופה בתנור וחוזר ומטגנה במחבת: **מנחת פתים.** מלמד שטעונה פתיתה:
@15 **המשיח תחתיו מבניו.** המשיח מבניו תחתיו: **כליל תקטר.** אין נקמצת להיות שיריה נאכלין אלא כלה כליל, וכן כל מנחת כהן של נדבה כליל תהיה טז **כליל.** כלה שוה לגבוה:
@19 **המחטא אתה.** העובד עבודותיה שהיא נעשית חטאת על ידו: **המחטא אתה יאכלנה.** הראוי לעבודה, יצא טמא בשעת זריקת דמים שאינו חולק בבשר, ואי אפשר לומר שאוסר שאר כהנים באכילתה חוץ מן הזורק דמה, שהרי נאמר למטה (פסוק כב) כל זכר בכהנים יאכל אתה:
@20 **כל אשר יגע בבשרה.** כל דבר אוכל אשר יגע ויבלע ממנה: **יקדש.** להיות כמוה, אם פסולה תפסל, ואם היא כשרה תאכל כחמר שבה: **ואשר יזה מדמה על הבגד.** ואם הזה מדמה על הבגד, אותו מקום דם הבגד אשר יזה עליה, תכבס בתוך העזרה: **אשר יזה.** יהא נזה, כמו (איוב טו כט) ולא יטה לארץ מנלם, יהא נטוי:
@21 **ישבר.** לפי שהבליעה שנבלעת בו נעשה נותר, והוא הדין לכל הקדשים: **ומרק.** לשון תמרוקי הנשים (אסתר ב יב) אישקורימינ''ט בלע''ז [נקוי] : **ומרק ושטף.** לפלוט את בליעתו, אבל כלי חרס למדך הכתוב כאן שאינו יוצא מידי דפיו לעולם:
@22 **כל זכר בכהנים יאכל אתה.** הא למדת שהמחטא אותה האמור למעלה לא להוציא שאר הכהנים, אלא להוציא את שאינו ראוי לחטוי:
@23 **וכל חטאת** וגו' **.** שאם הכניס מדם חטאת החיצונה לפנים פסולה: **וכל.** לרבות שאר קדשים:
@24 **קדש קדשים הוא.** הוא קרב ואין תמורתו קרבה:
@25 **ישחטו.** רבה לנו שחיטות הרבה, לפי שמצינו אשם בצבור, נאמר ישחטו רבים. ותלאו בעולה להביא עולת צבור לצפון:
@26 **ואת כל חלבו** וגו' **.** עד כאן לא נתפרשו אמורין באשם, לכך הצרך לפרשם כאן, אבל חטאת כבר נתפרשו בה בפרשת ויקרא (פרק ב) : **את האליה.** לפי שאשם אינו בא אלא איל או כבש, ואיל וכבש נתרבו באליה:
@28 **אשם הוא.** עד שינתק שמו ממנו. למד על אשם שמתו בעליו או שנתכפרו בעליו, אף על פי שעומד להיות דמיו עולה לקיץ המזבח, אם שחטו סתם, אינו כשר לעולה קודם שנתק לרעיה. ואינו בא ללמד על האשם שיהא פסול שלא לשמו, כמו שדרשו הוא, הכתוב בחטאת, לפי שאשם לא נאמר בו אשם הוא, אלא לאחר הקטרת אמורין, והוא עצמו שלא הקטרו אמוריו כשר:
@29 **קדש קדשים הוא.** בתורת כהנים הוא נדרש:
@30 **תורה אחת להם.** בדבר זה: **הכהן אשר יכפר בו.** הראוי לכפרה חולק בו, פרט לטבול יום ומחסר כפורים ואונן:
@31 **עור העלה אשר הקריב לכהן לו יהיה.** פרט לטבול יום ומחסר כפורים ואונן שאינן חולקים בעורות:
@32 **לכהן המקריב אתה** וגו' **.** יכול לו לבדו, תלמוד לומר לכל בני אהרן תהיה. יכול לכלן, תלמוד לומר לכהן המקריב, הא כיצד לבית אב של אותו יום שמקריבין אותה:
@33 **בלולה בשמן.** זו מנחת נדבה: **וחרבה.** זו מנחת חוטא ומנחת קנאות שאין בהן שמן:
@35 **אם על תודה יקריבנו.** אם על דבר הודאה על נס שנעשה לו, כגון יורדי הים והולכי מדברות וחבושי בית האסורים וחולה שנתרפא שהם צריכין להודות שכתוב בהן (תהלים קז כא. כב) יודו לה' חסדו ונפלאותיו לבני אדם ויזבחו זבחי תודה. אם על אחת מאלה נדר שלמים הללו, שלמי תודה הן, וטעונות לחם האמור בענין, ואינן נאכלין אלא ליום ולילה, כמו שמפורש כאן: **והקריב על זבח התודה.** ארבעה מיני לחם חלות, ורקיקין, ורבוכה, שלשה מיני מצה, וכתיב (פסוק יג) על חלת לחם חמץ וגו' , וכל מין ומין עשר חלות, כך מפורש במנחות (עז א) . ושעורן חמש סאין ירושלמיות שהן שש מדבריות, עשרים עשרון: **מרבכת.** לחם חלוט ברותחין כל צרכו יג **יקריב קרבנו על זבח.** מגיד שאין הלחם קדוש קדשת הגוף להפסל ביוצא וטבול יום ומלצאת לחלין בפדיון, עד שישחט הזבח:
@37 **אחד מכל קרבן.** לחם אחד מכל מין ומין יטול תרומה לכהן העובד עבודתה, והשאר נאכל לבעלים ובשרה לבעלים, חוץ מחזה ושוק שבה, כמו שמפורש למטה (פסוקים כט. לב) תנופת חזה ושוק בשלמים. והתודה קרויה שלמים:
@38 **ובשר זבח תודת שלמיו.** יש כאן רבויין הרבה, לרבות חטאת ואשם ואיל נזיר וחגיגת ארבעה עשר, שיהיו נאכלין ליום ולילה: **ביום קרבנו יאכל.** וכזמן בשרה זמן לחמה: **לא יניח ממנו עד בקר.** אבל אוכל הוא כל הלילה, אם כן למה אמרו עד חצות, כדי להרחיק אדם מן העברה:
@39 **ואם נדר או נדבה.** שלא הביאה על הודאה של נס, אינה טעונה לחם ונאכלת לשני ימים, כמו שמפורש בענין: **וממחרת והנותר ממנו.** בראשון יאכל. וי''ו זו יתרה היא, ויש כמוה הרבה במקרא, כגון (בראשית לו כד) ואלה בני צבעון ואיה וענה, (דניאל ח יג) תת וקדש וצבא מרמס:
@41 **ואם האכל יאכל** וגו' **.** במחשב בשחיטה לאכלו בשלישי הכתוב מדבר. יכול אם אכל ממנו בשלישי יפסל למפרע, תלמוד לומר המקריב אותו לא יחשב, בשעת הקרבה הוא נפסל, ואינו נפסל בשלישי. וכן פרושו בשעת הקרבתו לא תעלה זאת במחשבה, ואם חשב פגול יהיה: **והנפש האכלת ממנו.** אפלו בתוך הזמן עונה תשא:
@42 **והבשר.** של קדש שלמים אשר יגע בכל טמא לא יאכל: **והבשר.** לרבות אבר שיצא מקצתו, שהפנימי מתר: **כל טהור יאכל בשר.** מה תלמוד לומר, לפי שנאמר (דברים יב כז) ודם זבחיך ישפך וגו' והבשר תאכל, יכול לא יאכלו שלמים אלא הבעלים, לכך נאמר כל טהור יאכל בשר: **והבשר כל טהור יאכל בשר.** כלומר כל מה שאסרתי לך בחטאת ואשם, שאם יצאו חוץ לקלעם אסורין, כמו שכתוב (ו ט) בחצר אהל מועד יאכלוה, בבשר זה אני אומר לך כל טהור יאכל בשר אפלו בכל העיר:
@43 **וטמאתו עליו.** בטמאת הגוף הכתוב מדבר, אבל טהור שאכל את הטמא, אינו ענוש כרת, אלא באזהרה והבשר אשר יגע בכל טמא וגו' (פסוק יט) . ואזהרת טמא שאכל את הטהור אינה מפורשת בתורה, אלא חכמים למדוה בגזרה שוה. שלש כריתות אמורות באוכלי קדשים בטמאת הגוף, ודרשוה רבותינו בשבועות (ז א) אחת לכלל ואחת לפרט ואחת ללמד על קרבן עולה ויורד, שלא נאמר אלא על טמאת מקדש וקדשיו:
@47 **יעשה לכל מלאכה.** בא ולמד על החלב שאינו מטמא טמאת נבלות: **ואכל לא תאכלהו.** אמרה תורה יבוא אסור נבלה וטרפה ויחול על אסור חלב, שאם אכלו, יתחיב אף על לאו של נבלה, ולא תאמר אין אסור חל על אסור:
@49 **בכל מושבתיכם.** לפי שהיא חובת הגוף ואינה חובת קרקע, נוהגת בכל מושבות, ובמסכת קדושין בפרק א' (לז א) מפרש למה הצרך לומר: **לעוף ולבהמה.** פרט לדם דגים וחגבים:
@53 **ידיו תביאינה** וגו' **.** שתהא יד הבעלים מלמעלה והחלב והחזות נתונין בה, ויד כהן מלמטה ומניפן: **את אשי ה'.** ומה הן האשים, **את החלב על החזה יביאנו.** כשמביאו מבית המטבחים נותן החלב על החזה, וכשנותנו ליד הכהן המניף נמצא החזה למעלה והחלב למטה, וזהו האמור במקום אחר (ויק' י טו) שוק התרומה וחזה התנופה על אשי החלבים יביאו להניף וגו' , ולאחר התנופה נותנו לכהן המקטיר, ונמצא החזה למטה, וזהו שנאמר (ויק' ט כ) וישימו את החלבים על החזות ויקטר החלבים המזבחה. למדנו ששלשה כהנים זקוקין לה, כך מפורש במנחות (סב א) : **את החלב על החזה יביאנו.** ואת החזה למה מביא, להניף אותו הוא מביאו, ולא שיהא הוא מן האשים. לפי שנאמר את אשי ה' את החלב על החזה, יכול שיהא אף החזה לאשים, לכך נאמר את החזה להניף וגו' :
@54 **והקטיר הכהן את החלב.** ואחר כך והיה החזה לאהרן, למדנו שאין הבשר נאכל בעוד שהאמורים למטה מן המזבח:
@55 **שוק.** מן הפרק של ארכבה הנמכרת עם הראש עד הפרק האמצעי, שהוא סובך של רגל:
@56 **המקריב את דם השלמים** וגו' **.** מי שהוא ראוי לזריקתו ולהקטיר חלבו, יצא טמא בשעת זריקת דמים או בשעת הקטר חלבים, שאינו חולק בבשר לד **התנופה' התרומה.** מוליך ומביא, מעלה ומוריד לז **ולמלואים.** ליום חנוך הכהנה:
@63 **קח את אהרן.** פרשה זו נאמרה שבעת ימים קודם הקמת המשכן, שאין מקדם ומאחר בתורה: **קח את אהרן.** קחנו בדברים ומשכהו: **ואת פר החטאת** וגו' **.** אלו האמורים בענין צואת המלואים בואתה תצוה, ועכשיו ביום ראשון למלואים חזר וזרזו בשעת מעשה:
@64 **הקהל אל פתח אהל מועד.** זה אחד מן המקומות שהחזיק מועט את המרבה:
@66 **זה הדבר.** דברים שתראו שאני עושה לפניכם צוני הקדוש ברוך הוא לעשות, ואל תאמרו לכבודי ולכבוד אחי אני עושה. כל הענין הזה פרשתי בואתה תצוה:
@69 **את האורים.** כתב של שם המפורש:
@70 **וישם על המצנפת.** פתילי תכלת הקבועים בציץ נתן על המצנפת, נמצא הציץ תלוי במצנפת:
@72 **ויז ממנו על המזבח.** לא ידעתי היכן נצטוה בהזאות הללו:
@73 **ויצק' וימשח.** בתחלה יוצק על ראשו, ואחר כך נותן בין ריסי עיניו ומושך באצבעו מזה לזה:
@74 **ויחבש.** לשון קשירה:
@76 **ויחטא את המזבח.** חטאו וטהרו מזרות להכנס לקדשה: **ויקדשהו.** בעבודה זו: **לכפר עליו.** מעתה כל הכפרות:
@77 **ואת יתרת הכבד.** על הכבד (שמות כט יג) לבד הכבד, שהיה נוטל מעט מן הכבד עמה:
@83 **איל המלאים.** איל השלמים, שמלואים לשון שלמים, שממלאים ומשלימים את הכהנים בכהנתם:
@87 **וחלת לחם שמן.** היא רבוכה, שהיה מרבה בה שמן כנגד החלות והרקיקין, כך מפורש במנחות (עח א) :
@89 **ויקטר המזבחה.** משה שמש כל שבעת ימי המלואים בחלוק לבן: **על העלה.** אחר העלה. ולא מצינו שוק של שלמים קרב בכל מקום חוץ מזה:
@95 **צוה ה' לעשת.** כל שבעת הימים. ורבותינו זכרונם לברכה דרשו לעשות. זה מעשה פרה. לכפר. זה מעשה יום הכפורים, וללמד שכהן גדול טעון פרישה קודם יום הכפורים שבעת ימים, וכן הכהן השורף את הפרה:
@96 **ולא תמותו.** הא אם לא תעשו כן, הרי אתם חיבים מיתה:
@97 **ויעש אהרן ובניו.** להגיד שבחן שלא הטו ימין ושמאל:

@2 **ראוי** שתדע כי בעולה התדירה דבר בזה המקו' כי הוא אשר ימצא שיתאכלו אבריה בכל לילה ולילה והוא תמיד של בין הערבים ואמנם תמיד של שחר זכר בסוף כאמרו ובער עליה הכהן עצים בבקר בבקר וערך עליה העולה וזאת תורת החטאת וזאת תורת האשם ראוי הוא להשלי' ביאור מה שזכר מהם כפרש' הקודמת הנה יחוייב שיהיה עניין תמיד של בין הערבים נרמז בפרש' הקודמת ולזה ביארו רבותינו שאמרו בעניין העולה בפרש' הקודמת. ונתנו בני אהרן הכהן אש על המזבח וערכו עצים על האש. שב לתמיד של בין הערבים. וזה יתבאר עוד כי לא מצאנו עריכת העצי' רק בעבור התמידין ולפי שמצאנו זה בזה המקום בלשון יחיד ושם בלשון רבים והיה מה שבזה במקום לתמיד של שחר ידענו כי מה שנזכר במקום ההוא איננו לתמיד של שחר ולזה יהיה לתמיד של בין הערבים ובכלל הנה תמיד של שחר ותמיד של בין הערבים לפי שהם מכוונים לדבר אחד בעינו. ראוי שלא יתחלפו זה מזה בענין עריכת עצים ר"ל שלכל אחד מהם יערכו עצים והסבה בחיוב זאת העריכה בשניהם היא אחת כמו שהתבאר מדברינו במה שיבא וגם כן מפני שאמ' על מוקדה הנה ראוי שיהיה שם מוקד שמיוחד לה לבד וזה אמנם יהיה העצים הנערכים על האש שעליהם ישימו איברי העולה ופדרה ולפי שאמר היא העולה על מוקדה על המזבח למדנו שהיא אחרונה לכל הקרבנות הקרבים ביום ההוא אלא אם יביא בה הכרח שיקרב אחריה קרבן אחר כמו הענין בקרבן פסח שהיה קרב אחר תמיד של בין הערבים ולמדנו מזה שמהפכין כל הלילה באיברי' שלא התאכלו עד הבקר כי אף על פי שהקרבת הקרבנות לא תהיה בלילה כמו שהתבאר מהשרשים הכוללים הנה עכול מה שהקריב ביום ישלם בלילה וזה כולל לעות התמיד ולשאר הקרבנות כי אין ראוי כשיקריבו עולת בין הערבי' שיוציאו משם איברי שאר הקרבנות אבל ראוי שתשלם שם הקטרתם כמו שצותה התורה ואש המזבח תוקד בו רוצה לומר שעם זה המוקד שיהיה יוקד במזבח כל הלילה לעכול הקרבנות היה שם מוקד אחר יוקד בו והוא האש שיקחו ממנו אש למזבח הקטרת כי כבר התבאר הפרשת אחרי מות כי מעל מזכה העולה יקחו מלא המחתה גחלי אש וראוי היה שיהיה זה האש מערכה בפני עצמה כי כבר צוה השם יתעלה שלא יקטיר בו מכל הקרבנות זולתי הקטרת הסמים ואם היה שיקחו זה האש מהמערכה אשר יקריבו עלית הקרבנות לא היו נמלטים שלא יתערב במחתה דבר מה מאברי הקרבנות המאוכלים ויתבאר שזאת המערכה השנית היתה למערב מזבח העולה לפי שאמר בפרש' אחרי מות ולקח מלא המחתה גחלי אש מעל המזבח מלפני השם למדנו שזה האש ייוחד מהאש האחר מהמערכת הגדולה שהיא לפאת מערב וראוי היה להיות כן למעלת הקטרת על הקרבת שאר הקרבנות הנה כמו שיחדה לו התורה מזבח בפני עצמו יותר קרוב לקדש הקדשים כן יחדה לו התורה מערכת האש יותר קרבה לקדש הקדשים ולזאת הסבה בעינה היה ראוי שיהיה הדלקת המנורה מזאת המערכת השנית ולמדנו מזה שאמו תוקד בו שאין הרצון שיציתו האש למטה ויביאוהו אל זאת המערכה אבל יחוייב שתהיה הצתתו בגוף המזבח:
@3 **ולבש הכהן מדו בד ומכנסי בד ילבש על בשרו והרים את הדשן.** למדנו שהרמת הדשן היא עבודה מן העבודות ולזה דקדקה התורה שתהיה על ידי כהן ובבגדי כהן ולא זכרה הורה כל הבגדים להשענה על מה שנזכר בבגדי כהונה שלא ישרתו כי אם בהם ולזה יחוייב שתהיה זאת בבגדי כהונה בכללם ואמנם הוצרכה התורה להזכיר בכאן לבישת בגדי כהונה לפי שהיה עולה על הדעת שלא תהיה העבודה בבגדי כהונה שלא יתלכלכו הבגדי' ההם בדשן המזבח:
@3 **והרים את הדשן אשר תאכל האש.** עם העולה יחד הם הגחלים העליונים אשר איברי העולה סמוכים להם ולזה יהיה זה הדשן הגחלים הפנימיות ואולם הרמת זה הדשן הוא כשיחתה הגחלים העליונים עם איברי העולה אילך ואילך עד שיראו הגחלים הפנימיות עממיות והוא הדשן הנזכר בזה המקום הולכת העצים אינה צריכה כהן:
@3 **ושמו אצל המזבח.** ר"ל שיקחהו במחתה ויורידהו וישימהו אצל המזבח במה שנזכר במה שקדם שהוא מקום דשן והוא אצל מזרח המזבח:
@4 **ופשט את בגדיו ולבש בגדים אחרים.** ראוי שנדע שאלו הבגדים האחרים הם בגדי כהונה גם כן שאם היתה הכונה שלא יצטרכו בגדי כהונה בז לא היה צריך לומר כי אם ופשט את בגדיו והוציא את הדשן ועוד שאמרו אחרים יחוייב שיהיו ממין הבגדים הראשונים ואולם אמרה התורה שילבש בגדי כהונה אחרים שיהיו פחותים מהראשונים להורות שזאת העבודה היא למטה מהעבודה הראשונה:
@4 **והוציא את הדשן אל מחו למחנה אל מקום טהור.** ר"ל האפר אשר על המזבח הנאכל בשלמו' כי הגחלים העליונים ואברי העולה ישארו שם וזה האפר יוציאוהו מחוץ למחנה אל מקום שפך הדשן הנזכר בפרשת ויקרא אל מקום טהור שאם היה טמא יטהרנו והאש על המזבח תוקד בו רוצה לומר שאחר זה יעשה שתוקד אש על המזבח בו בעצמו לא שיציתו האש למטה יעלוהו שם וזה אמנם יהיה כשיערכו שם העצים וידליקום שם וראוי שיהיו פני המדליק לפני יי' שהוא לצד המערב כי כבר דקדקה התורה בזה בכל הענינים כמו שתראה ומפני זה יהיה התחלת הבערתה מפאת מזרח של המערכה:
@5 **לא תכבה.** הוא מצות לא תעשה והמכבה לוקה:
@5 **ובער עליה הכהן עצים בבקר בבקר.** ר"ל על האש המערכה והם שני גזירי עצים שהיה מביא לערוך עליהם העולה באופן שתהיה העולה על העצים ולפי שלא התנה שיהיה שם כהן כי אם בהבערת העצים למד בו שהולכת העצים אינה צריכה כהן:
@5 **וערך עליה העולה והקטיר עליה חלבי השלמים.** למדנו מזה שהעולה היא ראשונה לכל הקרבנות רוצה לומר עולת התמיד ועליה יהיו שאר הקרבנות יאמר בזה המקום והקטיר עליה חלבי השלמים ואמר בפרשת ויקרא בחטאת ובמנחת חוטא והקטיר המזבחה על אשי יי':
@6 **אש תמיד תוקד על המזבח לא תכבה.** היא מערכת שלישית יערכנה באופן שתוקד על המזבח כמו שקדם במערכות האחרות והנה זה ראש לא ישמש דבר אלא שהוא שם תמדיי לא תכבה היא מצות לא תעשה והמכבה אותו לוקה ושתקה התורה מהזהיר על כבוי אש המערכה השלישית היא לצורך מזבח הקטרת לפי שהענין קל וחומר רוצה לומ' שאחר שהזהיר על האש שישתמשו בו במזבח העולה שלא יכבהו כל שכן שתקפיד התורה באש שישתמר בו למזבח הקטרת שהוא יותר נכבד:
@7 **וזאת תורת המנחה הקרב אותה בני אהרן.** ראוי שתדע שזאת ההקרבה כוללת קבלת המנחה בכלי שרת והולכתה לפני המזבח כמו שההקרבה הנזכרת בראש ויקרא כוללת קבלת הדם והולכתו למזבח כמו שבארנו שם ובכלל הנה לא מצאנו במנחה שיהיה רשות לבעלים כי אם להביאה אל הכהן וזה לאות כי מה שאחר ההבאה ההיא לא יהיה כי אם על ידי הכהן ובכלל הנה מתנאי ההקרבה אל המזבח שיהיה מתקבל בכלי ובכלי ההוא יוליכה והנה זה הכלי יחוייב היותו מכלי שרת:
@7 **לפני יי' אל פני המזבח.** הנה מפני שפני המזבח הם לדרומו כי שם היה הכבש הוא מבו' שאם היתה ההגשה שם לא תהיה לפני יי' שהוא למערב ולזה יחוייב שתהיה ההגשה באופן שתהיה לצד המערב שהוא לפני יי' ותהיה ההגשה עם זה אל פני המזבח שהוא הדרום וזה אמנם ישלם כשתהיה ההגשה על קרן דרום מערבית על חודה של קרן כשילך הכהן ופניו למערב לפאת דרום עד שיגיע שם:
@8 **והרים ממנו בקמצו וגו'.** כבר בארנו במה שקדם זאת הקמיצה איך תהיה וששיעור הלבונה הוא ג"כ קומץ והנתרת ממנה יאכלו אהרן ובניו מפני שאמר זה אחר אמרו והקטיר המזבח למדנו שלא יותירו שירי מנחה לכהנים כי אם אחר הקטרת הקומץ והלבונה והקדים אהרון לבניו ללמד שכהן גדול נוטל חלק בראש:
@9 **מצות תאכל במקו' קדוש בחצר אהל מועד יאכלוה.** הוא לפנים מן הקלעים וצוה השם יתעלה שיאכלוה מצות לא חמץ. כמו שאמר אחר זה לא תאפה חמץ וזה המאמר אמנם הוא בשירי המנחות ולזה הוא מבואר שהאופה חמץ שירי המנחה לוקה וכן המחמץ אותה כי התורה זכרה אחד ממעשה תקון החמץ וחייבה עליו והוא הדין בשאר המעשים ויורד שכן הוא שכבר אמר במנחה במה שקדם לא תעשה חמץ ואמנם זכר הנה האפייה לחייב על כל מעשה ומעשה ואמר במנחה במה שקדם כל המנחה אשר תקריבו ליי' לא תעשה חמץ וזה כולל הקומץ ושירי המנחה ולזה יחוייב מלקות על אי זה מהם שיהיה אם עשאו חמץ:
@10 **חלקם נתתי אותה מאשי קדש קדשים היא בחטאת וכאשם.** שהם קדש קדשים כל זכר בבני אהרן יאכלנה פרט לבנות אהרן. והנה למדנו מזה שאפילו בעלי מומים חולקין בה לפי שהם ראוים לאכילתה חק עולם לדורתיכם מאשי יי' הנה אין הכהנים זוכים בה אם לא אחר שיתוארו כשהם אשי יי' וזה יהיה אחר שהוקטר במזבח הראוי לו:
@11 **כל אשר יגע בהם יקדש.** למדנו שאין זה אלא מפני מה שנבלע מהם בדבר הנוגע בהם ולפי שהוא קדש הנה יהיה בקדושה ההיא הדבר שנבלע בו דבר ממנו והנה למדנו זה ממה שאמר בחטאת מזה הענין כמו שיתבאר במה שיבא זה קרבן אהרן ובניו אשר יקריבו ממנו ליי' ביום המשח אותו למדנו שבזה הקרבן ישוה בהן כהן המשיח לכהן הדיוט ולפי שאמר אחר זה והכהן המשיח תחתיו מבניו יעשה אותה חק עולם למדנו שאין זה נוהג אלא בכהן משיח שאם היה נוהג בכל כהן לא היה צריך לזכור זה וזה הפך מה שנזכר קדם זה ולזה יתבאר שהיותר תמידיי הוא מיוחד בכהן משיח ואולם בעת החנוך ישוו בזה כהן משוח לכהן הדיוט ולזה זכר ביום המשח אותו שמורה על חנוך הכהן הגדול והכהן ההדיוט ואף על פי שאינו נמשח הנה עת התחנכו דומה ליום המשח של כהן גדול וראוי שתדע כי לא יתכן שיאמר ביום המשח אותו בעבור כהן גדול כי אין זה הקרבן מיוחד בו ביום המשיחה לבד אבל הוא תמידיי ויתבאר עוד שתמידות זאת המנחה אינו נוהג כי אם בכהן גדול כי לא מצאנו דבר מהענינים התמידיים בבקר ובערב במקדש שהיה נכפל וזה מבואר מאד במנורה ובהקטרת הסמים ובתמידים ולזה יחוייב שיהיה זה נוהג מנהגם רוצה לומר שלא יעשה ממנו כי אם אחר לא הרבה כמו שהיה מחוייב אם יעשה אותו כהן גדול ומזה המקום יתבאר שאין מתנאי זאת המנחה התמידיית שיהיה המקריב אוו כהן משוח אבל תנהג בכל כהן גדול ואמנם זכרה תורה משוח לפי שמדרך כהן גדול שיהיה נמשח בשמן המשחה עשירית האיפה סלת מנחה תמיד מפני שזכר סלת שיורה על הקמח היותר יפה הנה הוא מבואר שזה יהיה מן החטים וכן הענין בשאר המקומות אשר זכרה התורה סלת וראוי שיקחוהו מהחטי' היותר משובחים להמשך לכוונת התורה שיהיה זה קרבן היותר נבחר שאפשר מחציתה בבקר ומחציתה בערב למדנו שהיא קרבה חציין ולזה אם אבד או נטמא המחצית האחד יחוייב שיביאו עשרון אחד ויחצו אותו לשניים ומחציתו יקחו באופן שיהיה זה הקרבן בבקר ובערב מחצית העשרון והוא מבואר מענין זה הקרבן שאף על פי שמת כהן גדול לא תפסק הקרבתו עד שימנו כהן גדול אחר כי זה הקרבן צוה להיות תמידיי ותמידותו ידמה שינהג מנהג שאר הדברים התמידיים במקדש שלא יפסק עניינם מה שהתמיד העבודה במקדש וראוי שתדע שאמרו מחציתה בבקר ומחציתה בערב יהיה במנחה התמידיית והיא מנחת כהן גדול לא במנחת כהן הדיוט והנה המנחה ההיא תהיה עשירית האיפה כי אין שם שיעור במנחה יותר קטן לפי מה שהתבאר בתורה על מחבת בשמן תעשה לפי שכבר נתבאר במנחת מחבת שהוא סלת בלולה בשמן יהיה אמרו בשמן בזה המקום מורה על שמן אחר יקבלוהו במחבת ואופן הטגון בזה האופן שתבאר מן החוש שישלם בשלשת לוגין לעשירי' האיפה מורבכת תביאינה רוצה לומ' שקודם שתשימנה על מחבת תהיה מורבכת וזה יהיה כשתהיה חלוטה ברותחין החלה הבלולה בשמן ואחר כך יקלוה מחבת בשמן תופיני הרצון בו לפי הוראת הגדר מה שהוא ממוצע בין בשל ונא מנחת פתים שיהיו פותחין החלות האלו ולפי שכבר ידענו שמנחת מחבת היא מנחת פתים יהיה אמרו פתים בזה המקום מורה על עניין אחר לפי שכבר הקפידה התורה שיהיה זאת המנחה קרבה חציין למדנו שאמרו פתי' בזה המקו' הוא שלא תהיינה שם בבקר כי אם חצי החלות ובערב חצייהם הנשארים כאלו תאמר שיחצו כל חלה וחלה ויקחו החי האחד ממנה בבקר והחצי האחר בערב ולפי עניין זאת המנחה התמידית נלמד שהיא נעשית שתי' עשרה חלות שכן מצינו בלחם הפני' שידמה היותו לזאת הכוונה בעינה שהיא שתים עשרה חות וזה יתבאר ממה שאמרנו בזה בפרשת ויקחו לי תרומה:
@14 **תקריב ריח ניחוח ליי'.** ראוי שתדע שכבר יהיה עמה קומץ לבונה והיא גם כן חציין חציין קרב כי כבר זכרה התורה באלו המנחות שתבא עמהם לבונה וזה כולל לכל המנחות אלא אם תבאר התורה שלא יתן עליה לבונה כמו שבארה במנחת חוטא ולפי שזכר אהרן שב לבאר שזה ינהג בכל כהן גדול ולזה אמר והכהן המשיח תחתיו מבניו יעשה אותה רוצה לומר שיהיה נבחר לכהן גדול מבניו שהם הכנים הדיוטים:
@15 **חק עולם ליי' כליל תקטר.** רוצה לומר שלא ירימו ממנו קומץ אבל עולה כולה כליל ולפי שאמר חק עולם ליי' למדנו שאין להקרבתה הפסק ולזה חוייב כשמת כהן גדול שיקריבוה יורשיו עד שיתמנה כהן גדל אחר:
@16 **וכל מנחת כהן כליל תהיה לא תאכל.** רוצה לומר שאין מקריבין ממנה קומץ ויאכלו השירים כמו הענין במנחת ישראל אכל עולה כלה כליל והאוכל ממנו עובר על לא תעשה שנאמר לא תאכל וזה אמנם יהיה במנחת כהן לא במנחת כהנת:
@18 **זאת תורת החטאת במקו' אשר תשחט העולה תשחט החטאת.** רוצה לומר בצפון העזרה כמו שאמר במה שקדם על ירך המזבח צפונה לפני יי'. ולמדנו מזה שמקום שחיטת כל עולה וחטאת היא בצפון העזרה:
@18 **לפני יי'.** רוצה לומר שתהיה השחיטה לפני יי' וזה ישלם כשיהיו פני הנשחט ופני השוחט לצד קדש הקדשים:
@18 **קדש קדשים הוא.** למדנו מזה שכבר דקדקה התורה שתהיה שחיטתה בצפון מפני היותר קדש קדשים ומזה המקום יתבאר שכל מה שהוא קדש קדשים תהיה שחיטתו בצפון ושמה שאינו קדש קדשים לא נקפיד בו שתהיה שחיטתו בצפון:
@19 **הכהן המחטא אותה יאכלנה.** ראוי שתדע שאין הכונה בזה שלא יאכל ממנה כי אם הכהן המקריב אותה כי כבר אמרה בפרשת אמור אל הכהנים בבעל מום לחם אלהיו מקדשי הקדשים ומן הקדשים יאכל שהוא מבואר שהוא אינו ראוי להקריב ועוד שכבר אמר בזה המקום חלק כחלק יאכלו שירה כי הכהנים חולקים ביניהם מה שיזכו בו מהמתנות רוצה לומר אנשי בית אב של אותו היום ועוד שאם היה כן לא יתכן שתצוה התורה שלא יותירו ממנה. כי אי אפשר לפי הנהוג שיאכל אדם אחד כל בשר בהמה אחת בסעודה אחת או בשתים ולזה תהיה הכונה בזה הכהן שראוי לעבודה להוציא את הטמא ולא להוציא בעל מום מפני מה שנזכר בפרשת אמור אל הכהנים כמו שזכרנו:
@19 **במקום קדוש תאכל בחצר אוהל מועד.** הוא לפנים מן הקלעים:
@20 **כל אשר יגע בבשרה יקדש.** לפי שזכר בשרה שיבלע ממנו דבר הנוגע בו למדנו שמצד הבליעה הקפידה התורה בזה ולזה לא ינהג זה בנגיעה שתהיה בעצמות החטאת וגידיו הקשים ומזה המקום יתבאר שלא יקדש להיותה כמוה רק שיהיה נבלע בו ממנה דבר והטעם כי דבר הבלוע הוא קדש קדשים ולזה ינהג זה הדין בדבר שהוא בלוע בו וזה מבואר שזה ראוי שינהג בכל הקדשים רצוני' לומר שאם נבלע מהם דבר יהיה עליו חומר מה שהוא נבלע בו:
@20 **ואשר יזה מדמה על הבגד אשר יזה עליה.** מפני שאמר מדמה אשר יזה עליה למדנו שזה יהיה קודש ההזאה ובדם הראוי להזאה והוא הדם שיקבלו בכלי שרת ויש בו שיעור הזאה ובמה שידמה לו שיהיה אפשר שיבלע בו הדם בו ממה שראוי לקבל טומאה כמו שק ועור הרך:
@20 **תכבס במקום קדוש.** רוצה לומ' שיהיו מכבסין אותה בעזרה באופן שלם כדי שייוסר ממנה הדם הנבלע בה:
@21 **וכלי חרס אשר תבושל בו ישבר.** הטעם מפני מה שנבלע ממנה בו והוא נפסל בלינה כמו שיתבאר בענין הקדשים וזה אין דרך להוציא הבלוע מהכלי חרס ולזה יחוייב שישבר וראוי שנדע ששבירתו הואר במקום קדוש כמו הענין הכבוס הבגד וכן העניין במריקה ושטיפה במים לכלי הנחשת אשר תבושל בו כי הכוונה בזה הוא מפני דבר הבלוע שמקום אכילתו הוא בעזרה וראוי שלא נוציא דבר חוץ ממחיצתו כמו שנתבאר מאמרו בפרשת ואלה המשפטים ובשר בשדה טרפה לא תאכלו וראוי שתדע שכן הדין אם שמו בכלי חרס תבשיל רותח של חטאת אך בכלי נחשת אף על פי שלא בשלוהו בו כי בעבור הבליעה יהיה זה הדין ואם בכלי נחשת בשלה ומורק ושוטף במים הנה המריקה תהיה בחמין והשטיפה אחר זה בצונן וזה יתבאר מצד הוראת הגדר וזה אמנם יהיה במים ולא בשאר משקין כי זה הנהוג והתורה דקדקה שתהיה במים ובזה האופן יסור הדבר הבלוע מכלי נחשת והנה נזכר מזה הענין בדם ובבשול לא ינהג כי אם בחטאת הנשחטת כי בה ידבר שנאמר תשחט החטאת ולזה לא ינהג זה בחטאת העוף ולא ינהג זה הדין גם כן בחטאת הנפסלת או הנשרפת כי הם אינם נאכלות והוא ידבר בה המקום בחטאת הנאכלת שנאמר במקום קדוש תאכל בחצר אהל מועד וראוי שהמריקה והשטיפה תנהג בכל הקדשים הנאכלים כדי שלא יפסל בלינה כל זכר בכהנים יאכל אותה למדנו מזה שלא תאכל ממנו כהנת:
@22 **קדש קדשים היא.** למדנו מזה שלא תאכל כהנת קדשי קדשים:
@23 **וכל חטאת אשר יובא מדמה אל אהל מועד לכפר בקדש לא תאכל.** למדנו מזה שאף חטאת יחיד שהיא נאכלת אם בא אפילו מקצת דמה אל אהל מועד לכפר בקדש לא תאכל נפסל אפילו שאר דמה ולזה לא תהיה נאכלת לא למזבח ולא לכהנים כי זריקת הדם מכשיר האמורים למזבח והקטרת האמורים מתיר הבשר לכהנים ואם באשם ולא הזה ממנו בקדש אם היתה כוונתו כשהביאו שם שיכפר בו בקדש הנה נפסל חטאת וראוי שנדע שכמו זה הדין יהיה בדם הנכנס בקדש אם הכניסוהו לבית קדשי הקדשים כי היחס אחד וכן ראוי שנדע שהבשר שנכנס מהחטאת לאהל מועד כשר שנאמר מדמה ולא מבשרה. וכן ראוי שנדע שהדם שיוצא חוץ למחיצתו במקום למטה בקדוש' ממחיצתו שהוא נפסל אבל לא נשפוט בזה שיהיה נפסל כי אם היוצא כמו הענין בבשר שיצא חוץ למחיצתו כי מה שחדש בזה המקום שיהיה מקצת הדם הנכנס באהל מועד פוסל שירי הדם לא נלמוד ממנו לשאר ענייני יציאת הדם ממחיצתו:
@23 **באש תשרף.** אי איפשר שנאמר שיהיה נשרף במזבח העולה כי אין למזבח העולה מהחטאת כי אם האמורים אבל יהיה נשרף במקום אשר ישרפו בו הדברים אשר אינם קרבים לשם יתעלה ולפי שלא ביאר שלא יהיה נשרף מחוץ למחנה. אבל אמר סתם באש תשרף למדנו שהוא נשרף במקומו בעזרה במקום מוכן שם לשרוף פסולי המוקדשין. ואחשוב שזה המקום היה לצד המזרח כמו הענין במקום הדשן וראוי שנבין מזה המקום שהחטאות הנשרפות אשר מחוקם להוציאם חוץ לעזרה אם אירע בהם פסול בחוץ לא ישרפו במחיצתן אבל ישרפו חוץ לעזרה במקום מוכן שם לזה והנה לא בארה התורה אלו המקומות כמו שבארה מקום השלכת מוראת העוף להעיר שכל מקום כשר לזה והוא שיהיה בעזרה במה שנשרף בעזרה או חוץ לעזרה במה שנשרף חוץ לעזרה וראוי שתדע שאין ראוי שיפורש וכל חטאת אשר יובא מדמה אל אהל מועד החטאת אשר מדרכו שיובא מדמו אל אהל מועד והם החטאות הנשרפות שאם היה הדבר כן לא היה ראוי שיאמר באש ישרף לפי שכבר באר זה במה שקדם ועוד שהוא מדבר עתה בחטאות הנאכלות ועוד שכבר יורה לשון התורה שהבאת דמו לכפר בקדש סבת החיוב שלא תאכל רוצה לומר שלולי זה כבר היה נאכל וזה המאמר לא יתכן כי אם בחטאות הנאכלות וראוי גם כן שתדע שכבר כלל באמרו לא תאכל החטאות הנשרפות ולזה אמר וכל חטאת אשר יובא מדמה אל אהל מועד שאם היתה הכוונה בזה בחטאות הנאכלות לבד לא היה צריך לומר וכל חטאת אבל היה אומר ואם יובא מדמה אל אהל מועד ואמרו באש תשרף שם גם כן לכל אלו החטאות והכונה בו בחטאות הנשרפות שלא ישרף כמצוות אל שפך הדשן אבל ישרף באופן השרף פסולי המוקדשים:
@24 **וזאת תורת האשם במקום אשר תשחט העולה ישחט האשם.** רוצה לומר לצפון העזרה:
@25 **ואת דמו ישפך על המזבח סביב.** כמו העניין בעולה וזה נוהג באשם לפי שנאמר זאת תורת האשם:
@26 **ואת כל חלבו יקריב וגו'.** כבר התבאר כל זה במה שקדם:
@30 **הכהן אשר יכפר בו לו יהיה.** רוצה לומר ההן הראוי לכפר בו והם אנשי בית אב של אותו היום ואמר אשר יכפר בו להוציא הטמא אך הבעל מום חולק עמהם כמו שבארנו בפרשה הקודמת ולמדנו מזה שלא זכה בו הכהן עד שיתכפרו בו הבעלים וראוי שנבין שכן העניין בחטאת שנאמר הכהן המחטא אותה יאכלנה רוצה לומר כשחטא אותה כמשפטי התורה:
@31 **והכהן המקריב את עולת איש עור העולה אשר הקריב לכהן יהיה.** למדנו שעור העולה הוא לאנשי בית אב ולא יזכו בו אלא לאחר הקרבה שנאמר עור העולה אשר הקריב ועוד שגדר העולה לא ידבק כי אם בנעשת כמצותה והנה בארה התורה בעור העולה שהוא לכהנים וממנו יתבאר מקל וחמר שעור החטאת והאשם הוא לכהנים לפי שכבר זכו בו הכהנים בבשרם ולזה בארה זה התורה בעולה לפי שהיא עולה כליל והיה עולה על הדעת שלא יהיה לכהנים חלק בה:
@32 **וכל מנחה אשר תאפה בתנור וגומר לכהן המקריב אותה לו תהיה.** רוצה לומר לאנשי בית אב הטהורים כמו שקדם והיא גם כן נאכלת לזכרי כהונה לפנים מן הקלעים כי היא קד קדשים ובאר שאין חולקין מנחה כנגד מנחה ולזה הפריד המנחה האחת מן האחרת להורות שכל אחת מהם חולקין ביניהם ולזה אמר וכל מנחה אשר תאפה בתנור וכל נעשה במרחשת ועל מחבת וגו' ולא אמר וכל מנחת תנור ומרחשת ומחבת:
@33 **וכל מנחה בלולה בשמן וחרבה.** רוצה לומר מנחת הסלת וחרבה תקרא הסלת שאין עמה שמן כי היא יבשה כמו הענין במנחת חוטא ובמנחת סוטה:
@33 **לכל בני אהרן תהיה איש כאחיו.** ראוי שנדע כי אין ראוי שתהיה הבדל בחלוקת המנחה לכהנים ובין מנחת הסלת ובין שאר המנחות וזה מבואר מצד עצם העיון ועוד שכבר אמר במנחת חוטא והיתה לכהן כמנחה למדנו מזה שאין הבדל בעניין היות המנחה לכהן בין מנחה למנחה ועוד שכבר יורה זה שתהיה לכהן המקריב אותה ועוד שלא יתכן שיחלק עשרון סלת לכל הכהנים בכללם כי לא יגיע לאחד מהם בזה האופן חלק מוחש ולזה יחוייב שתהיה הכונה באמרו לכל בני אהרן תהיה איש כאחיו לכל אנשי בית אב של אותו היום והנה לא אמרה תורה בזה המקום לכהן המקריב אותה לו תהיה לשתי סבות האחת ללמד לנו כי מה שאמרה לכהן המקריב אותה לו תהיה אין הרצון בו שיקריב בפעל אבל הכוונה בו הראוי להקריב אז והם אנשי בית אב והשנית שאם אמרה בזה המקום לכהן המקריב אותה לו תהיה היינו חושבים שלא תחלק זאת המנחה כלל לאנשי בית אב אבל יקח אותה האחד מהם והוא המקריב אותה לפי שאינה ראויה ליחלק באופן החלק מנחת מאפה תנור או מנחת מחבת או מרחשת כי המנחות ההם הם אפויות ואי זה חלק שיגיע מהם לכהן הוא ראוי לו לאכלו אבל מנחת הסלת תחסרה לישה ואפייה ולזה לא יהיה החלק המגיע לאחד מאנשי בית אב ראוי בפני עצמו ולזה בארה לנו התורה שזאת המנחה גם כן החלק לאנשי בית אב והם משתי אלו הלשונות שאמרה התורה בזה המקום בזכירת הכהנים בקדשי הקדשים למדנו שכונת התורה היא שיהיו נחלקים לאנשי בית אב כי הם הראוים אז להקריב מפני שהוא יומם ולא יצא מכלל החלוקה הבעל מום ואם אינו ראוי להקריב הוא ראוי לאכול וכבר בארה התורה שכהן בעל מום חולק עם אנשי בית אב כמו שזכרנו ולמדנו מאמרו איש כאחיו שאין הקטן חולק בקדשי הקדשים:
@34 **וזאת תורת זבח השלמים אשר יקריב ליי'.** הוצרך בזה המקום לזכור אשר יקריב ליי' לפי שהוא נאכל לבעלים והיה עולה על הדעת שלזאת הסבה לא יצטרך שיהיו מעשיו לשם הקב"ה וכבר ביא' בפרשה הקודמת עשית השלמים במה שיכלל כל מיני השלמים ועתה שב לבאר כל מה שנתייחדו בו מיני השלמים מקצתו לקצת והוא שאם יקריבנו על תורה יקריב עמם מיני השלמים ועתה שב לבאר כל מה שנתייחדו בו מיני השלמים מקצתו לקצת והוא שאם יקריבנו על תודה יקריב עמם מיני לחם בשלם שבפנים והם כולם מהחטים שהרי זכר סלת אמר וסלת מרבכת חלות בלולות בשמן והנה יראה שמיני הלחם שזכר יהיה מנושא אחד בעינו לפי שהחלפון שזכרה התורה בהם הוא באופן התקון לבד ולזה יהיה קצו חמץ וקצתו מצה והקצת שהוא מצה יהיה קצתו חלות מצות בלולות וקצתו מצות השוחין בשמן ושני אלו המינים הם מאפה תנור וקצתו רכיכין והם חלות בלולות בשמן וחולט אותם ברותחים עד שתאפה כל צרכה ואחר כך קולה אותה על המרחשת בשמן כי היא זאת הכוונה במה שאמר מורבכת לפי הוראת הגדר וראוי שתדע כי שיעור מה שיעשה חמץ הוא כשיעור מה שיעשה מצה שנאמר על חלות לחם חמץ אחת וכבר יורה אמרו על שניות במספר ולפי שאחרי המספר יחוייב שיהיו מסכימים יהיה שעור חמץ כשיעור המצות בכללם כמו שבארנו זה בענין הלבונה הבאה עם המנחות:
@35 **אם על תודה יקריבנו. ביום הקריבו את זבחו יאכל.** רוצה לומר שלא יחשב על מי שיעשה זה הפעל הרצוי והוא הכהן שיאכלו הבעלים מבשרו ביום השלישי ולזה תהיה בעת אמרו ואם האכל יאכל מבשר זבח שלמיו ואם יחשב שיאכלהו הבעלים ביום השלישי הנה לא ירצה הזבח במה שיעשו להגעת הרצוי והוא השחיטה וקבלת הדם והולכתו וזריקתו כי לכל אלו העבודות הם מהכרח הגעת הרצוי. וראוי שנדע שלא תפגל זאת המחשבה הזבח אלא כשחשב בהם המרצה בעבודות אשר הם מהכרח הרצוי כי מפני ששלל הרצוי מפני זאת המחשבה ראוי שיהיה הרצוי מגיע במה שיעשהו אז הבעל המחשבה ההוא לולי זאת המחשבה שתמנענו ומזה המקום יתבאר שלא יתפעל הזבח אלא במחשבת הפועל עבודות הרצוי וכשיהיה ראוי שיגיע הרצוי על ידו המקריב אותו לא יחשב לו המחשב רוצה לומר שלא יחשב על יד הכהן המרצה שיאכלוהו בעלים חוץ לזמנו פגול יהיה והנפש האוכלת מבשר זה הזבח שחשבו בו זאת המחשבה עונה תשא רוצה לומר שהוא בכרת וכן אמר על זה הבאור בפרשת קדושים תהיו ואוכליו עונה ישא כי את קדש יי' חלל ונכרתה הנפש ההיא מעמיה. ולמדנו מה המקום שכל מקום שנאמר בתורה עונו ישא הרצון בו שתכרת הנפש ההיא והנה זכרה זה התורה בקל וממנו נלמד בחמור והמשל שכבר בארה התורה בשלמים שאם יחשב שיאכלוה הבעלים מהם חוץ לזמן אכילתם נתפגלו ואם הקפידה התורה בזה בשלמים שהם קדשים קלים כל שכן שתקפיד בזה בקדשי קדשים ולזה יהיה זה הדין נוהג בכל מיני קדשים רוצה לומר שאם חשב הכהן בעבודות שהם מתנאי הרצוי שיאכל בשר הקרבן אחר זמנו נתפגל הקרבן וכמו זה מאופן יתבאר שאם חשב שיהיה נקטר למזבח הנקטר מהקרבן ההוא שם חוץ לזמנו שהוא פגול. וזה שאם הקפידה התורה בזה בנאכל לבעלים כל שכן שתקפיד בנאכל לגבוה והוא מה שהקטירו מהקרבן ההוא על המזבח. ולזה יתבאר שכבר יתפגל הקרבן בכמו זאת המחשבה הן בנאכל לכהנים בן בנאכל למזבח וראוי שנדע שזה הדין ינהג בקרבן שיתכן שיאכל ממנו למי שהיתה המחשבה לו שיאכל חוץ לזמנו כמו הענין בבשר זבח השלמים שנעשו בהלכתן שיתכן שיאכלו ממנו הבעלים שהיתה המחשבה שיאכלוהו חוץ לזמנו וזה יתחייב ממנו שיהיה זה הזבח כשר ושיהיה מה שנפלה המחשבה בו ראוי לאכילה רוצה לומר שיהיה בו שיעור אכילה שהוא כזית ושיהיה ראוי לאכילה כמו הבשר לא שתהיה המחשבה בזאת בעצמות והגידים והקרנים והטלפים. ראוי שתדע שזה הדין לא ינהג אלא במה שיש לו מתירין לאדם או למזבח כמו הענין בבשר השלמים הנזכר פה שיש לו מתירין והוא זריקת הדם והקטרת האמורין אבל מה שאין לו מתירין לאדם או למזבח אם היתה המחשבה לו הנה לא תהיה המחשבה כפולת כי מתנאי המחשבה המפגלת מה שנזכר פה שתהיה בעת עשיית הפעל אשר הוא מהכרח הרצוי ובדבר אשר באלו הפעולות בו רושם להתירו לאכילה לאדם אם היתה המחשבה לאדם או למזבח אם היתה המחשבה למזבח והנה אמרו לא יחשב לו הוא מצות לא תעשה ולמדנו ממנו שהכהן מוזהר שלא יחשב כמו זאת המחשבה שתפסיד הקדשים ולפי שאנחנו נמצא כי מתנאי הקדשים הזמן והמקום רוצה לומר שכבר קבעה התורה זמן לאכילתם הן לאדם הן למזבח כמו שהתבאר במה שקד' וקבעה עם זה מקום יאכלו בו. וזה שקדשי הקדשים נאכלים לפניו מן הקלעים שהוא מקום קדוש כמו שיתבאר וקדשים קלים אכילתם לפנים מן החומה בירושלם כמו שיתבאר במה שיבא הנה ראוי שנעיין אם הוא ראוי שנלמד מזה שתהיה מחשבת המקום מפגלת ר"ל אם חשב שיאכל קרבן חוץ למקומו. ונאמר שכבר בארה התורה בפרשת קדושים תהיו כי הטעם בפגול הוא מפני שכבר חל את קדש יי' והוא מבואר שהבשר יתחלל בעצמותו אם יעבור זמנו כי ישוב הבשר נבאש ונבזה ואם יצא חוץ למקומו לא יתחלל מעצמותו אלא שאינו במקום קדוש כמו המקום שהיה בו. ולזה יתבאר שלא יתפגל מצד מחשבת המקום. אבל יהיה פסול אחר שהקפידה התורה במחשבות בעניין הקרבנות וראוי שנדע שהאוכל את הנותר חייב כרת וזה שאם נתחייב כרת באכילתו תוך זמנו מפני שחשבו בו לאכלו חוץ לזמנו כל שכן שיתחייב כרת כשאכלו חוץ לזמנו באמת וזה מבואר מאד והבשר אשר יגע בכל טמא ר"ל בשר קדש שנטמא כי בבשר קדש ידבר בזה המקום והנה כלל באמרו כל הטמאות הקלות והחמורות הנזכרות בתורה:
@35 **והקריב על זבח התודה.** למדנו שזבח התודה הוא העקר ולחמי התודה הם באים בכלל הזבח. והנה לא נתבאר בתורה שיעור הלחם הבא עם התודה. והנה מצאנו בתורה מבואר שיעור הלחם הבא עם שני כבשי עצרת שהוא עשרון והוא חמץ. ולזה ידמה שכל לחם ולחם מהחמץ יהיה שעורו עשרון. ולפי שכבר אמר והקריב ממנו אחד מכל קרבן תרומה ליי' שיהיו לחמי החמץ לכל הפחות עשרה כי לא מצאנו תרומה בפחות מזה המספר בתורה ולזה יתבאר שהחמץ יהיה עשרה עשרונות שהוא איפה כי העשרון הוא עשירית האיפה וממה שקדם יתבאר שמיני המצה יהיו גם כן עשרה עשרונות ולזה יהיו לחמי תודה באים מעשרים עשרונות. ויתבאר ממה שקדם שבכל מין ומין יהיו עשרה לחם עד שיהי המספר החלות ארבעים. ולפי שאמר חלות מצות חלות לחם הנה יחוייב שתהיינה שלמות לא פרוסות וכן מה שיקח הכהן הוא אחד שלם פרוס שנאמר והקריב ממנו אחד מכל קרבן יי' והנה השיעור שישימו מהשמן כאלו החלות לפי הנהוג מענינם כשיתוקנו למאכל היה לוג רביעיתו לרקיקין ורביעיתו לחלות מאפה תנור וחצי לרכיכין וראוי שנדע שכבר אפשר להרים תרומת הלחם הזה בעיסה כמו העניין בחלה כי שם נאמר בכ' תרומה:
@37 **לכהן הזורק את דם השלמים לו יהיה.** למדנו מזה שהוא ראוי שיהיה הכהן ראוי בשעת זריקת הדם רוצה לומר שאם היה הכהן טהור בשעת קבלת הדם או הולכתו ואינו טהור בשעת זריקה אינו חולק בלחמי תודה עם אנשי בית אב. והנה הרצון באמרנו הזורק הראוי לזרוק מצד הזמן והם אנשי בית אב של אתו היום ובשר זבח תודה שלמיו ביום קרבנו יאכל ראוי שנדע שאין הכוונה בזה שיאכל קדם בא הלילה שכבר אמר אחר זה לא יניח ממנו עד בקר ואמנם הכוונה בו תוך יום אחד מעת הקרבתו ולא יהיה זה ג"כ מעת לעת אבל יהיה גבול אכילתו עד סוף הלילה והסבה כי אז יהיה הבשר יותר נבחר ממה שיהיה כשיעבור זה הזמן ובאר זה התורה בקצת קדשים קלים ולמדנו מזה שכן הדין בקדשי הקדשים רוצה לומר שאין נאכלים כי אם עד בקר הבא ראשון כי אם הקפידה בזה התורה עם היותר מהקדשים קלים כל שכן שתקפיד בזה בקדשי הקדשים ולפי שאין ממנהג האנשים לאכול בלילה אחר חצי הלילה הנה ראוי שיאכלם קדם עבור חצות הלילה אלא שלא יפסל בנותר עד יעבור הלילה. ואחשוב שקרבן זבח תודה בא על עניין נתינת הודאה לשם במה שהשפיע מהטובות. ולזה נקרא תודה. ולזה תמצא כשיוסיפו על העיר שיקדו התוספת ההוא בב' תודות. לפי מה שהתבאר קצת באור מעזרא ובתודות ההם היו אומרים ארוממך יי' כי דלותני שהוא ענין הודאה על הטובות שהשפיע וידמה כשיסמך על זבח התודה היה אומר בו וודוי הודאה לשם יתעלה כי זה הקרבן לא היה בא על עון:
@39 **ואם נדר או נדבה זבח קרבנו ביום הקריבו את זבחו יאכל.** למדנו מזה המצוה מן המובחר לאכלו ביום הראשון אך לא יפסל הנותר ולזה אמר אחר זה וממחרת והנותר ממנו יאכל או תהיה וי"ו והנותר נוספת כמו וי"ו ואיה וענה. נרדם ורכב וסוס. עניינו וממחרת הנותר ממנו יאכל:
@40 **והנותר מבשר הזבח ביום השלישי באש ישרף.** מפני שלא אמר והנותר ממנו עד בקר למדנו שבבא הלילה אחר עבור היום השני יהיה נפסל בנותר ואמרו באש ישרף יחוייב העשותו בו לפי מה שיתבאר מהשרשים הכוללים ולזה ימתינו לשרפו עד בקר יום שלישי וישרפוהו הבעלים בבתיהם במקום שהיו נאכלים בו כי לא צותה התורה בזה המקום שיוציאוהו מחוץ לשרפו:
@41 **ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה.** הנה בביאור זה הפסוק מהעומק וקושי וזה אי אפשר שנאמר שתהיה הכוונה בזה במה שיובן ממנו בתחלת העיון רוצה לומר שאם יאכל מבשר הזבח ביום השלישי שלא ירצה וזה שכבר התבאר בפרשת אחרי מות כי בזריקת הדם תשלם הכפרה אמר שם ואני נתתיו על המזבח לכפר על נפשותיכם כי הדם הוא בנפש יכפר ואחר שלמה הכפרה אין ראוי שיאמן שישוב החטא על עניינו. ובכלל הנה אחר שנרצה הזבח לא יתכן שישוב להיות בלתי נרצה וזה מבואר בנפשו ולזה גם כן יתבאר שאמרו המקריב אותו לא יחשב לו אין הרצון בו שלא יהיה נחשב לו לדבר הזבח אשר אכלו ממנו אחר זמנו ולזה יהיה יחשב לו מעניין מחשבה. והרצון בו שלא יחשב זה העניין למקריב אותו שהוא בעל הזבח כמו שאמר ברא' זאת הפרשה אשר יקריב ליי':
@42 **באש ישרף.** מפני שלא ביאר זכר מקום אחר שריפתו הנה תהיה שריפתו במקום אכילתו אלא אם היה מקום אכילתו מכניס מחייב שלא נכנס הטומאה לשם כמו העניין בעזרה ולזה אם נטמא בעזרה בשר קדשי הקדשים שהוא נאכל שם ישרף ואם יצא חוץ לעזרה ונטמא שם ישרף במקומו כי לא נוכל להכניס הטמא בעזרה:
@42 **והבשר כל טהור יאכל בשר.** ר"ל כי כבר הורשה כל טהור לאכל בשר קדש מזבח השלמים אך אם יאכל ממנו הטמא יתחייב כרת והנה בארה התורה זה הדין בקדשים קלים וממנו יתבאר בקדשי קדשים מקל וחומר ואמרו וטמאתו עליו ירצה בו שיהיה טמא מצד עצמו כאלו תאמר שהיה זב ומצורע או בעל קרי ואמרו ונפש כי תגע בכל טמא הוא בטמאה שיהיה לאדם מצד המגע בדבר הטמא כאלו תאמר שנגע בטומאת אדם כמו זובו ושכבת זרעו או שנגע בזב ומצורע ונדה ושאר מה שידמה לזה או בבהמה טמאה היא הנבלה:
@44 **או בכל שרץ טמא.** הם שמנה שרצים הנזכרים בתורה שיטמא הנוגע בהם כמותם:
@46 **זכרה** התורה אלו המינים לפי שמהם יביאו הקרבנות ולכבוד הקרבנות רצה שלא יאכל חלב אלו הבהמות אף על פי שלא יהיו קרבנות:
@47 **וחלב נבלה וחלב טרפה יעשה לכל מלאכה ואכול לא תאכלוהו.** הנה הנבלה היא לפי מה שיורה עליו הגדר שנזבחה שלא כדרך הזביחה הראויה והטרפה היא שמתה מעצמה או שיש בה חולי או מכה אי אפשר לחיות ממנה כאלו תאמר שטרפה זאב או ארי ואמרו לכל מלאכה רצה בו שכבר הותר לנו ליהנות בו בכל מלאכות כאלו תאבד במשיחה או בהדלקה אבל יאסר באכילה והוצרך להזכיר חלב נבלה וחלב טרפה שלא יחשוב חושב שלא ינהג איסור מחלב אלא בבהמות הראויות להקריב אשי ליי' ולמדנו מזה המקום שהאוכל חלב נבלה וטרפה יתחייב משום חלב גם כן ואם הוא חייב מפני היותו מנבלה וטרפה מצד אחר כמו שיתבאר:
@48 **כי כל אוכל חלב מן הבהמה אשר יקריבו ממנו אשה לה' ונכרתה.** אין ספק שאין הרצון בזה שיקריב ממנה בפעל שכבר זכר בכללות כל חלב שור וכבש ועז לא תאכלו ואין הרצון בזה גם כן שתהיה הבהמה ההיא ראויה להקריב מנה אשה לה' שלא תהיה בעלת מום וזה שכבר זכר נבלה וטרפה ולזה הוא מבואר שהרצון בזה שאינה נאות להקריב ממנה אשה ליי' והבהמה שבזה התואר הוא שור וכבש ועז והנה למדנו מזה המקום שלא נאסר מהחלבים אלא מה שמדרכו להיות קרב להם מאלו הבהמות כי יראה שלכבוד הקרבנות מנע החלב כמו שיבאר במה שקדם:
@49 **וכל דם לא תאכלו בכל מושבותיכם לעוף ולבהמה** אין ראוי שנאמין שיהיה דם החיה מותר כי כבר נתבאר בסדר ויקרא בכללות שכל דם הוא אסור וכן יתבאר זה בפרשת קדושים תהיו ולזאת הסבה צוה שם לכסות דם חיה ועוף ולזה יתבאר שאמרו ולבהמה נכלל בו חיה ובהמה כי שם בהמה יאמר בכללות על החיה והבהמה אמר זאת הבהמה אשר תאכלו כיל וצבי ויחמור וכן הענין בחיה אמר בפרשת ויהי ביום השמיני זאת החיה אשר תאכלו מכל הבהמה אשר על הארץ והנה סמכה התורה צווי אסור החלב והדם אחר זכרון תורת השלמים. כי לזאת הסבה נצטוו שלא יאכלו במדבר כי אם שלמים כמו שזכרנו במה שקדם וזה יתבאר עוד בפרשת אחרי מות:
@52 למדנו מזה שדין התנופה ינהג **בבני ישראל** ולא בבנות ישראל ולא בגוים:
@52 **המקריב את זבח השלמים ליי'.** הם הבעלים:
@52 **יביא את קרבנו ליי' מזבח שלמיו.** רוצה לומר שהבעלים מביאים בידיהם מה שהוא קרב להשם מזבח השלמים וזה שאם היה על תודה יביא בידיו אחד מכל קרבן מהלחם:
@53 **ידיו תביאנה את אשי יי'.** רוצה לומר שהבעלים יביאו בידיהם החלבים שהם אשי השם ועמהם יביאו מה שיהיה מהמזבח לכהנים וזה הדבר השני כולל התודה והשלמים ואמנם הבאת הלחם המיוחד בתודה וראוי שתדע כי הבאת אלו הדברים יחד בסדור הראוי נתבאר בפרשה הבאה אחר זה עם מה שזכר בזה המקום וזה שהלחם הבאה עם התודה יושם עליון שנאמר בפרשה הבאה אחר זדה ומסל המצות אשר לפני השם לקח חלת מצה אחת וחלת לחם שמן אחת ורקיק אחת ויושם על החלבים ועל שוק הימין ולפי שנאמר על החלבים ועל שוק הימין למדנו שהחלבים היו למטה ולמעלה מהם חלק הכהנים שהוא חזה התנופה ושוק התרומה והנשאר מאשי השם לפי שלא נזכר מקומו היה למעלה והוא שתי הכליות הכבד וכאשר היה שם לחם היה למעלה מהם כמו שביארנו:
@53 **את החלב על החזה יביאנו את החזה.** ירצה לפי מה שאחשוב שהשומן שאצל החזה יביאנו את החזה לכהן כי החלב יאמר על השומן אמר חלבו האליה תמימה ולא זכר בכאן כי אם החזה אך אחר זה זכר שוק הימין וקראו שוק התרומה וידענו כי החזה והשוק היו יחד בתנופה אמר בפרשת שמיני שוק התרומה וחזה התנופה על אשי החלבים להניף תנופה:
@54 **והקטיר הכהן את החלב המזבחה והיה החזה לאהרן ולבניו.** ר"ל שלא יזכו הכהנים בחזה ושוק אם לא אחר הקטרת החלבים במזבח ונאמר לאהרן ולבניו להורות כי כהן גדול נוטל חלק בראש אף על פי שאינו מקריב:
@55 **ואת שוק הימין תתנו תרומה לכהן מזבחי שלמיכם.** למדנו בזה המקום ששוק הימין הוא גם כן לכהן והנה יחס התרומה לשוק והתנופה לחזה ואם היתה להם יחד התנופה והתרומה לפי שתנועתיהם הטבעיות נאותות לזה ולזה וזה שתנועת החזה בבהמה היא הולכה והבאה וזה היא תנופה ותנועת השוק שהיא כלי ההליכה היא בהעלאה והורדה כן יעלה כל ב"ח רגליו ויורידם ובזה האופן יעתק המקום למקום:
@56 **המקריב את דם השלמים ואת החלב מבני אהרן לו תהיה שוק הימין למנה.** ר"ל הראויים להקריב אז והם אנשי בית אב כמו שביארנו במה שקדם ולמדנו שמי שהיה מהם טמא בעת זריקת הדם או בעת הקטרת החלבים איננו חולק בחזה ושוק:
@57 **ונתן אותם לאהרן הכהן ולבניו.** למדנו שכהן גדול קודם לבניו בחזה ושוק וממנו נלמד שכן העניין בשאר מתנות כהנה:
@58 **זאת משחת אהרן ומשחת בניו מאשי הש' ביום הקריב אותם לכהן להש'.** ר"ל זאת היה הגדלה שנתגדלו במשיחתם הכהנים מאשי השם ביום הקריב אותם השם יתעלה לכהן להשם כי אז נתן להם זה החלק מהקרבנות שנזכרו בזאת הפר' לעולה ולמנחה ולחטאת לאשם ולתודה ולזבח השלמים ואמר מאשי השם כי כבר נתן להם השם יתעל מתנות אחרות זולת אלו כמו שיבא ולהורות שאלו המתנות יהיו לכהנים לדורות אמר אחר זה אשר צוה השם לתת להם ביום משחו אותם מאת בני ישראל חק עולם לדורותיכם:
@60 **זאת התורה לעולה וגו'.** אמר ולמלואים לפי שמעשה המלואים והשלמים הם שנים והם דומים בענייניהם למעשה התודה אלא שלא היה במלואים לחם חמץ כמו שנזכר בפרשת ואתה תצוה ובזאת הפרשה הבאה ביום צוותו את בני ישראל להקריב קרבניהם להשם למדנו מזה שכל הקרבנו' ראוי שיהיו לשם הקב"ה ולמדנו מזה עוד שאחת מהכונות בקרבנות היתה שלא יקריבו קרבן לע"ז ולזה צוה אותם שיקריבו קרבניהם להשם למען לא יזבחו לע"ז ולזה אמר בפרשת אחרי מות ולא יזבחו עוד את זבחיהם לשעירים:
@62 זאת הפרשה דבקה לפרשת וזה הדבר אשר בסדר ואתה תצוה ושם ביארנו כל הנזכר בזאת הפרשה:
@92 **בשלו את הבשר פתח אהל מועד ושם תאכלו אותו ואת הלחם אשר בסל המלואים.** הנה נוהג איל המלואים ובלחמו מנהג קדשי הקדשים לאכלו במקום קדוש ולבשלו במקום קדוש ואם הוא כשלמים מפני שבו נשלם קדשת אהרן ובניו:
@94 **כי שבעת ימים ימלא את ידיכם.** ר"ל שבכל אחד מהשבעת ימים יעשה להם משה ככה כנזכר בזאת הפרשה להקריב עליהם אלו הקרבנות כי כן כתוב בפרשת ואתה תצוה ועשית לאהרן ולבניו ככה ככל אשר צויתי אותכה שבעת ימים תמלא את ידם:
@95 **כאשר עשה ביום הזה.** מכל הקרבנות והמעשים:
@95 **צוה ה' לעשות לכפר עליכם.** עד שכבר תצטרכו בכל יום מאלו השבעה ימים לפר חטאת להשלים הכפרה כמו שנזכר בפרשת ואתה תצוה ושם זכרנו התועלות המגיע מזה הפעל לחדש הכהונה והקדושה לאהרן ולבניו באופן שיהיו ראויים לכפר על זולתם והנה היו אלו הקרבנות נוהגים שבעה ימים כדי שיבינו מהם עם זה ההכפל מה שהיא הערה עליו באופן שיהיו נקיים בשלמות המחטאים עם שכבר היה זה גם כן לכפר על החטאים רבים דמו להם ולזה ראוי שיהיה ההכפל בזה הקרבן הראשון אשר בו נתחדשה להם הכהונה והיה בכל יום חטא ועולה ושלמים להודות על הגעת הרצוי להם בשלם שבפנים לפי מה שהורם מענין הקרבנות ובכאן נשלם הבאור בזאת הפרשה:
